// Let's examine the DOM structure of results and filters
const result = await browserjs(tabId, () => {
  // Check headings, links, filters, or cards
  const cards = document.querySelectorAll('.LocationResult, .c-location-card, .location-card, [data-location-id], [class*="Result"], [class*="result"]');
