const tabId = 248688717;

const data = await browserjs(tabId, () => {
  // Let's find all location cards and their text/details
  // Look for elements with location info
  const items = Array.from(document.querySelectorAll('.c-location-card, .LocationCard, [class*="location-card"], [class*="LocationCard"], .Locator-card, [class*="c-location-grid-item"]'));

  // Also let's inspect the inputs for filters
  const filterInputs = Array.from(document.querySelectorAll('input[type="checkbox"], input[type="radio"]')).map(input => {
    const label = input.closest('label') || document.querySelector(`label[for="${input.id}"]`);
    return {
      id: input.id,
      name: input.name,
      value: input.value,
      checked: input.checked,
      labelText: label?.textContent?.trim()
    };
  });

  return {
    itemCount: items.length,
    firstItemText: items[0]?.innerText?.slice(0, 500),
    filterInputs: filterInputs
  };
});

