const cardsData = await browserjs(tabId, () => {
  const titles = Array.from(document.querySelectorAll('.Teaser-title'));
  return titles.map(t => {
    // Find parent container representing the card
    let parent = t;
    for (let i = 0; i < 5; i++) {
      if (parent.parentElement && (parent.parentElement.classList.contains('Locator-result') || parent.parentElement.classList.contains('c-location-grid-item') || parent.parentElement.tagName === 'LI' || parent.parentElement.classList.contains('Teaser'))) {
        parent = parent.parentElement;
        break;
      }
      if (parent.parentElement) parent = parent.parentElement;
    }
    return {
      title: t.textContent?.trim(),
      cardText: parent.innerText?.trim()
    };
  });
});

